#!/usr/bin/env python3
"""Generates a benchmark scene of N small random spheres (default 1000) on a
ground sphere, lit by the sky. Used to check that the BVH and threads keep
render times in seconds.

Usage: python3 tools/gen_spheres.py [N] > scenes/spheres1000.scene
"""
import random
import sys

n = int(sys.argv[1]) if len(sys.argv) > 1 else 1000
random.seed(7)

print(f"""# {n} random spheres for speed testing.
# Generated by tools/gen_spheres.py; edit that script, not this file.

image_width  800
aspect_ratio 16/9
samples_per_pixel 32
max_depth    20
tonemap      aces

camera lookfrom 0 6 18  lookat 0 0 0  vup 0 1 0  vfov 35

material ground lambertian 0.5 0.5 0.5
material glass  dielectric 1.5
sphere 0 -1000 0  1000  ground
""")

for k in range(n):
    x, z = random.uniform(-12, 12), random.uniform(-12, 8)
    r = random.uniform(0.1, 0.35)
    kind = random.random()
    name = f"m{k}"
    if kind < 0.7:
        print(f"material {name} lambertian {random.random():.3f} {random.random():.3f} {random.random():.3f}")
    elif kind < 0.9:
        print(f"material {name} metal {random.uniform(0.5, 1):.3f} {random.uniform(0.5, 1):.3f} "
              f"{random.uniform(0.5, 1):.3f} {random.uniform(0, 0.3):.3f}")
    else:
        name = "glass"
    print(f"sphere {x:.3f} {r + random.uniform(0, 1.5):.3f} {z:.3f}  {r:.3f}  {name}")
